package com.shopsphere.controller;
import com.shopsphere.dao.AdminOrderDAO; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*;
@WebServlet("/admin/orders") public class AdminOrderServlet extends HttpServlet{private final AdminOrderDAO dao=new AdminOrderDAO();protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{try{r.setAttribute("orders",dao.findAll());r.getRequestDispatcher("/WEB-INF/views/admin/orders.jsp").forward(r,p);}catch(Exception e){throw new ServletException(e);}}protected void doPost(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{try{dao.updateStatus(Integer.parseInt(r.getParameter("orderId")),r.getParameter("status"));p.sendRedirect(r.getContextPath()+"/admin/orders");}catch(Exception e){throw new ServletException(e);}}}